import {encounterSalvage} from './economy.js?v=5.18.0';
import {defaultHero} from './mako.js?v=5.16.0';
import {makeEnemy} from './battle.js?v=5.38';
import {grantResonance} from './resonance-link.js';
import {reachableCells} from './townlife.js?v=5.38';
export const RIVALS=[
{id:'tamsin',name:'Tamsin',title:'The kiln guard',place:'refuge',chapter:2,role:'guard',sprite:3,school:'stone',support:'counter',xp:240,gold:120,gear:{id:'kiln-bracer',name:'Kilnkeeper’s bracer',power:6,hp:18},hint:'Break the bracer’s guard, then step out of the marked strike.'},
{id:'orren',name:'Orren',title:'The river medic',place:'sanctuary',chapter:7,role:'mender',sprite:4,school:'mercy',support:'field',xp:700,gold:260,gear:{id:'river-band',name:'Riverkeeper’s band',power:4,hp:45},hint:'Interrupt the restorative cast. Guard between your attacks to recover MP.'},
{id:'vela',name:'Vela',title:'The answering wind',place:'field',chapter:12,role:'predator',sprite:6,school:'wind',support:'echo',xp:1400,gold:500,gear:{id:'wind-wrap',name:'Answering windwrap',power:12,hp:25},hint:'Move out of the marked attack, then answer during the recovery.'}
];
export function rivalState(s){return s.rivals??={version:1,won:[],gear:[],lastReward:null};}
export function claimRival(s,id){const r=RIVALS.find(r=>r.id===id);if(!r||s.chapter<r.chapter)return false;const p=rivalState(s);if(p.won.includes(id))return false;p.won.push(id);p.gear.push(r.gear.id);s.xp+=r.xp;s.gold+=r.gold;s.items??={};for(const [key,count]of [['tonic',3],['ether',2],['revive',1]])s.items[key]=(s.items[key]||0)+count;s.supports??=[];const fresh=!s.supports.includes(r.support);if(fresh)s.supports.push(r.support);grantResonance(s,{sourceId:'rival:'+id,label:r.name+' · sparring lesson',points:1});p.lastReward={id,xp:r.xp,gold:r.gold,support:r.support,newSupport:fresh,gear:r.gear.id};return r;}
export function equipRivalGear(s,hero,gearId){const h=s.heroes?.[hero],gear=RIVALS.find(r=>r.gear.id===gearId)?.gear;if(s.mode==='battle'||!h||!s.recruited.includes(hero)||!s.rivals?.gear.includes(gearId)||s.heroes.some(x=>x.id!==hero&&x.rivalGear===gearId))return false;const old=RIVALS.find(r=>r.gear.id===h.rivalGear)?.gear;if(!gear||h.rivalGear===gearId)return false;const power=gear.power-(old?.power||0),hp=gear.hp-(old?.hp||0);h.power+=power;h.gearPower=(h.gearPower||0)+power;h.maxHp+=hp;h.gearHP=(h.gearHP||0)+hp;h.hp=Math.min(h.hp,h.maxHp);h.rivalGear=gear.id;return true;}
export function rivalEnemy(r){const e=makeEnemy(r.role,r.chapter,0);return {...e,name:r.name+' · '+r.title,rivalAvatar:r.sprite,hp:e.hp*2.4,maxHp:e.maxHp*2.4,power:e.power*1.15,move:r.title,color:'#e0c893'};}
export function installRivals(w){const objects=w.objects.bind(w),interact=w.interact.bind(w),win=w.winBattle.bind(w),lose=w.loseBattle.bind(w),cache=new WeakMap();w.objects=()=>{const list=objects(),r=RIVALS.find(r=>r.chapter===w.scene.chapter&&w.scene.key===r.place);if(!r||w.state.chapter<r.chapter||!w.state.story?.firstCore)return list;let o=cache.get(w.scene);if(!o){const cell=reachableCells(w.scene).find(x=>Math.hypot(x[0]-w.scene.arrive[0],x[1]-w.scene.arrive[1])>3&&!list.some(o=>o.xy&&Math.hypot(o.xy[0]-x[0],o.xy[1]-x[1])<2)&&list.filter(o=>o.type==='patrol').every(o=>(o.enemies||[]).every(e=>Math.hypot(e[1][0]-x[0],e[1][1]-x[1])>4)));if(!cell)return list;o={type:'npc',rivalId:r.id,name:r.name,label:r.name+' · optional sparring',sprite:r.sprite,xy:cell,chapter:r.chapter};cache.set(w.scene,o);}return [...list,o];};w.interact=o=>{if(!o?.rivalId)return interact(o);const r=RIVALS.find(x=>x.id===o.rivalId);if(w.state.mode!=='field'||!r)return;if(rivalState(w.state).won.includes(r.id))return w.text(r.name+': “You earned that lesson. Take it back to the road.”\nThis challenge’s rewards are already claimed.');w.choose(r.name+' · '+r.title+'\n'+r.hint+'\nVictory: '+r.xp+' XP · '+r.gold+' credits · '+r.gear.name+' · '+r.support+' support Mako · 3 tonics, 2 ethers, 1 revive · 1 discovery growth.\nOptional friendly sparring. Nothing is awarded for retreat or defeat.',[['Accept the challenge',()=>{w.state.mode='battle';w.currentBattle={scene:w.state.scene,mission:w.data.campaign.missions[r.chapter-1],object:{...o,type:'rival'}};w.callbacks.onBattle(w.currentBattle);}],['Another time',()=>{}]]);};w.loseBattle=()=>{if(!w.currentBattle?.object?.rivalId)return lose();w.currentBattle=null;w.state.mode='field';for(const h of w.activeHeroes){h.hp=h.maxHp;h.mp=h.maxMp;h.strain=0;}w.text('The sparring partner lowers their guard. “Enough for now. Come back when you want another round.” No reward claimed; the crew recovers.');};w.winBattle=()=>{const b=w.currentBattle;if(!b?.object?.rivalId)return win();const r=RIVALS.find(r=>r.id===b.object.rivalId);if(!r)return;w.currentBattle=null;w.state.mode='field';const reward=claimRival(w.state,r.id);if(!reward)return;encounterSalvage(w.state,{key:b.scene+':rival:'+r.id,type:'rival',region:r.chapter,core:'earth'}); // Reuse the normal level/mastery calculation with no generic drops or story flags.
settleRivalLevels(w.state);w.text(r.name+': “Well fought. Keep the equipment; I have another set.”\n'+r.gear.name+' · +'+r.xp+' XP · +'+r.gold+' credits · '+r.support+' support Mako · field supplies · +1 growth.\nOpen the small menu diamond to inspect your points, Mako and new gear.');};}

export function settleRivalLevels(s){const level=Math.min(45,1+Math.floor(Math.sqrt(s.xp/65)));for(const h of s.heroes){if(level>h.level){const fresh=defaultHero(h.id,level),oldMax=h.maxHp;for(const k of ['level','maxHp','maxMp','power','magic'])h[k]=fresh[k]+(k==='maxHp'?(h.gearHP||0):k==='power'?(h.gearPower||0)+(h.equipment?10:0):h.equipment&&k==='magic'?5:0)+(h.gridBonuses?.[k]||0);h.hp=Math.min(h.maxHp,h.hp+Math.max(0,h.maxHp-oldMax));}if(s.party.includes(h.id))for(const core of new Set(h.loadout.map(x=>x.core)))h.ap[core]=(h.ap[core]||0)+8;}}
